S = []  # (stufe_id, titel, untertitel, rows)
# row: (nr, paket, heute, loesung, wer, pushes, status)
S.append(("s0","Stufe 0 · Sicherheit","Kontoübernahme und Rechtsrisiko – vor allem anderen",[
("164b","Zwei-Faktor im Team","Mitarbeiter ohne Handy oder Notfall-Code konnten nur über das Supabase-Dashboard wieder hinein; niemand im Betrieb konnte helfen.","Chef und eine Vertretung setzen die Zwei-Faktor-Anmeldung zurück, der Betreiber hat eine eigene Tür im Command Center, Hilfe-Anfrage per Glocke.","G","1","live"),
("169","Konto-Schutz","Die Mitarbeiter-Einladung übernahm fremde Konten per E-Mail. Ein Chef konnte über die Login-Verknüpfung das Passwort fremder Personen setzen und ihre Zwei-Faktor löschen. Jeder Nutzer konnte sich selbst zum Admin machen. 24 Datenbank-Funktionen waren ohne Anmeldung aufrufbar.","Bestehende Konten werden nie übernommen, jedes Zurücksetzen prüft das Ziel-Konto, die Verknüpfung setzt nur noch der Server, Rolle und Tarif sind gesperrt, Funktionen nur noch mit Anmeldung bzw. nur für den Server.","G","1","live"),
("170","Admin-Doppelschloss","8 Admin-Routen prüften nur die Rolle „admin“. Der Website-Modus ließ ohne gesetzte Variable jeden Angemeldeten durch. Zwei Routen hatten ein eigenes Schloss ohne Zwei-Faktor.","Alle Admin-Wege prüfen Rolle, Betreiber-Kennung und Zwei-Faktor über eine zentrale Stelle; ein Test verhindert neue Lücken.","C","1","live"),
("173","Werbe-Mails rechtssicher","Autoresponder schickt Werbeserien an frei eingetippte Adressen ohne Einwilligung. Bewertungs-Bitten ohne Einwilligung und ohne Abmeldelink. Jede Website-Anfrage startet ungefragt eine Werbeserie. Termin-Nachfass ohne Abmeldelink, der Name aus dem Formular geht ungeschützt in die Mail (Phishing-Gefahr). Mails aus Abläufen kommen als „ARGONAUT OS“, Antworten landen bei info@. Abmeldung wirkt nur in einem Kanal. Newsletter prüft die Bestätigung nicht.","Werbung nur an bestätigte Einwilligungen, Abmeldelink und Widerspruchshinweis in jeder Werbe-Mail, eigenes Häkchen für die Dossier-Serie, Namen geschützt, Absender und Antwortadresse des Betriebs, eine Abmeldung stoppt alle Kanäle.","C","1","live"),
]))
S.append(("s1","Stufe 1 · Vor dem ersten weiteren Kunden","Mandantentrennung, Geld, KI-Regeln, Datenschutz, Testtag-Vorbereitung",[
("174","Mandanten-Lücken in der Datenbank","Ehemalige Mitarbeiter oder Fremde mit Kanal-Kennung können Team-Chat-Kanälen selbst beitreten und alles lesen. Ein Chef kann sich bezahlte Module selbst freischalten. Mitarbeiter können HR-Einträge bei einem fremden Betrieb anlegen. Chat-Absender lassen sich fälschen.","Beitritt nur im eigenen Betrieb, Modul-Freischaltung nur über den Betreiber, HR-Einträge immer beim eigenen Betrieb, Absender = angemeldete Person. SQL getrennt.","G","1","live"),
("175","Geld-Routen absichern","Rechnungs-, Mahnungs- und Auftragsbestätigungs-PDFs lassen sich ohne Login erzeugen. Die Kasse kann Lager auf fremde Artikel buchen. „Rechnung senden“ versendet auch für Mitarbeiter ohne Abrechnungsrecht. Ein Mitarbeiter kann ein ARGONAUT-Abo mit SEPA anlegen. „Rechnung neu berechnen“ prüft den Besitzer nicht.","Login-Pflicht für alle PDF-Routen, Artikel nur aus dem eigenen Betrieb, Senden nur mit Abrechnungsrecht, Abo nur durch den Chef, Besitzer-Prüfung in der Datenbank-Funktion.","G","1","live"),
("176","KI-Regeln einhalten","Die KI schätzt Marktpreise für Auftragspositionen (gegen die Grundregel). Die HR-Auswertung schickt Krankheitsmuster an die KI, der Dashboard-Chat die Namen Krankgemeldeter. Stapel-Aufträge fehlen im KI-Kostenprotokoll.","Platzhalter „Preis bitte ergänzen“, keine Krankheitsdaten an die KI (nur Anzahlen), Stapel-Kosten im Protokoll.","C","1","live"),
("177","Kündigungs-Sperre wirksam","Die Sperre für gekündigte Kunden liest eine Liste, in die nie jemand etwas einträgt. Gekündigte Kunden und ihre Mitarbeiter arbeiten weiter.","Sperre je Betrieb per Knopf in der Betriebs-Akte (mit Grund, jederzeit aufhebbar) – gilt für Chef, Mitarbeiter, Anmeldung und Schnittstellen. Automatisch ab Vertragsende, sobald die Stripe-Bestellstrecke steht.","G","1","live"),
("178","Datenschutzerklärung neu","Die Erklärung sagt „Anthropic anonymisiert“ und „Voyage entfernt Personenbezug“ – beides stimmt nicht. Resend, Ersatz-KI, PDF-Server, WhatsApp, Social-Schnittstellen, Messung und die Gesundheitsmodule fehlen.","Erklärung vollständig und richtig neu fassen, danach Anwalt; Baukasten-Vorlage für Kundenseiten mitziehen.","G","1","live"),
("179","Musterbetrieb XXL","Für den Testtag gibt es keinen Betrieb, in dem alle Module mit Daten gefüllt sind; jede Seite müsste von Hand befüllt werden.","Ein vollständiger Musterbetrieb mit Beispieldaten in allen Modulen, per Knopf anlegbar und wieder löschbar.","C","2","live"),
("180","Fachbeschreibung Elektriker","Das Dossier ist ein Werbetext; eine Beschreibung, was das System für eine Branche wirklich kann, fehlt.","8–12 Seiten für Laien, nur Gebautes, Vorgebautes als „in Vorbereitung“; danach Vorlage für alle Branchen.","C","0","live"),
("190","Zwei-Faktor-Pflicht je Betrieb","Pflicht für alle geht nur über eine Server-Variable für ganz ARGONAUT; der Inhaber kann sie für seinen Betrieb nicht selbst einschalten.","Schalter „Für alle Pflicht“ nur für den Inhaber (mit eigenem Code), Bestätigung mit Häkchen „Mitarbeiter informiert“ und „Betriebsrat einbezogen bzw. keiner vorhanden“, Nachweis wer/wann, 7 Tage Übergangsfrist, jederzeit abschaltbar.","G","1","live"),
("191","Cent-Rundung reparieren","Die Rundung rundete ab etwa 2 € halbe Cent ab: 0,5 × 8,79 € wurde 4,39 € statt 4,40 €, 19 % von 42,50 € wurden 8,07 € statt 8,08 € – gemessen bei 65.613 von 1 Mio. Beträgen und 604 von 40.000 Steuerbeträgen.","Eine zentrale Rundung ohne Gleitkomma-Fehler für Angebot, Rechnung, Kalkulator, Zahlung, Abo, SEPA, Mahnwesen, Finanzen und Gebühren; PDF und E-Rechnung zeigen alte Rechnungen centgenau wie verschickt (GoBD).","G","1","live"),
("192","Knopf-Abläufe und Glocke gezielter","Knopf-Abläufe drückt nur der Chef; Meldungen aus Abläufen gehen nur an den Chef oder an alle Mitarbeiter.","Je Ablauf Haken „Auch Mitarbeiter mit Schreibrecht dürfen starten“; Glocke zusätzlich an ausgewählte Personen oder eine Abteilung.","C","1","live"),
("193","KI-Modelle zentral nach Aufgabe","Welches KI-Modell eine Funktion nutzt, steht in jeder Datei einzeln; ein Modell-Wechsel heißt viele Stellen ändern.","Eine Zuordnung Aufgabe → Modell: günstiges schnelles Modell für interne Auswertungen, Zusammenfassungen und Hilfe; stärkeres Modell für Texte an Kunden. Im Ablauf-Baustein wählbar „intern“ oder „Kundentext“.","C","1","live"),
("194","Grundausstattung für alle","Viele Module für jeden Betrieb (Anfragen, Lager, Mahnwesen, Marketing, Bewertungen, Personal, Team-Chat …) lagen nur in einzelnen Branchen-Paketen oder hinter einem Betreiber-Schalter – für den Kunden sahen sie aus wie fehlend.","Alles Branchen-Neutrale gehört zum Kern (53 Module), Branchen-Pakete zeigen nur noch das Fachliche; Kalkulator ins Handwerk-Paket. SQL schaltet bei bestehenden Betrieben nur hinzu.","C","1","live"),
("195","Testzugang als Anfrage","„7 Tage kostenlos testen“ klang nach Sofortstart, obwohl kein Konto entsteht; die erste Test-Mail sagte „startklar“.","Knopf „Zugang anfordern“ mit Branche, Testseite in drei Schritten, 7 Tage ab Freischaltung; Martin schaltet jeden Zugang selbst frei.","C","1","live"),
("188","Voice Layer Stufe 1","Vorlesen nur mit der Browser-Stimme, klingt je Gerät anders und robotisch.","Deine geklonte Stimme über ElevenLabs, nur mit Login, Längen- und Tagesdeckel, Browser-Stimme bleibt Rückfall.","C","1","wartet auf Martin"),
]))
S.append(("s2","Stufe 2 · Bald","Rechte sauber ziehen, Lücken aus alten Modulen schließen",[
("181","Geld- und Personal-Seiten auf „Betrieb“","Auf 13 Seiten (Abo-Rechnungen, Eingangsbelege, Ausgaben, Reisekosten, Mitglieder, Personal, Provisionen, Nachkalkulation, Ernte-Zahlungen, Portal-Zugänge, Verträge, Fördervorhaben, Rückholung) speichern Mitarbeiter unter eigener Kennung – der Chef sieht diese Einträge nicht.","Speichern immer für den Betrieb, wie in Paket 165; SQL getrennt, weil es Mitarbeiter ohne Schreibrecht betrifft.","G","2","live"),
("182","Angebot-Link erst ab „versendet“","Ein Angebot im Entwurf ist per Link annehmbar, das Kundenportal zeigt Entwürfe, die Annahme speichert keinen Namen.","Link und Portal erst ab Status „versendet“, Annahme mit Name und Zeitpunkt.","G","1","live"),
("183","WhatsApp-Anmeldung mit Bestätigung","Eine Nummer ist nach dem Formular sofort aktiv; Dritte können fremde Nummern eintragen.","Nummer erst aktiv, wenn die Person per WhatsApp antwortet; Nachweis gespeichert.","C","1","live"),
("184","Dateien, Uploads, IBAN, Import","Einige Download-Wege vertrauen gespeicherten Pfaden – bei bekanntem Dateinamen fremde Datei abrufbar. Eine Tresenkraft lädt IBANs mit. Der Import erkennt Bank- und Werbe-Spalten nur am Namen. Speicher ohne feste Größen- und Typgrenzen, AU-Bescheinigungen unverschlüsselt.","Pfad muss zum Betrieb gehören, IBAN nur für berechtigte Rollen, Inhalte auf IBAN-Muster prüfen, Grenzen je Speicher, AU verschlüsselt.","C","1","live"),
("185","Schreibrechte der Mitarbeiter je Modul","An rund 175 Stellen dürfen Mitarbeiter über die Datenbank schreiben, auch wenn sie im Modul nur lesen dürfen. Lagerbewegungen dürfen sie löschen (GoBD). Abo-Rechnungen ohne Abrechnungsrecht.","Schreiben nur mit Modul-Schreibrecht, Löschen von Buchungen nur Chef, Abo-Rechnungen nur mit Abrechnungsrecht – schrittweise, SQL getrennt.","G","2","live"),
("186","Abläufe-Rest","Abläufe lassen sich nicht löschen. Ein abgestürzter Lauf bleibt ewig auf „läuft“. Ein nicht erreichbarer Webhook-Empfänger stoppt den Lauf ohne Neuversuch.","Löschen mit Rückfrage (Protokoll bleibt), hängende Läufe nach 2 Std. auf Fehler + Glocke, 3 Neuversuche über 24 Std.","C","1","live"),
("187","Sammelpaket klein","Prüf-Fälligkeiten rutschen einen Tag zurück und Monate laufen über (31.01. + 1 Monat = 03.03.). MRR-Kachel rechnet mit alten Preisen. Rechnungs-Knöpfe beim Mitarbeiter sichtbar. Artikel-Import überschreibt Filialbestände. Vereine bekommen Vertragsart „Studio“. Alte Crons nehmen das Geheimnis per URL. Keine volle CSP. 17 npm-Warnungen.","Jeden Punkt einzeln beheben, mit Tests; CSP zuerst im Beobachtungsmodus; Next.js 16.3.8 gegen Sicherheitslücken.","C","2","live"),
("187c","Speicher-Grenzen und Betrieb-Rest","Speicherordner ohne Größen- und Typgrenzen (HTML/SVG möglich). Korrespondenz, Bauplan-Pins, SEPA-Mandate und Nachkauf-Erinnerungen speichern beim Mitarbeiter unter eigener Kennung; Mitarbeiter legen Ratgeber-Seiten an, die nie erscheinen.","Grenzen je Speicherordner (großzügig über den Code-Grenzen), Speichern für den Betrieb, Ratgeber-Knopf nur für den Chef.","C","1","live"),
("187d","Personal-Cockpit schreibt für den Betrieb","Büroleitung mit Personal-Recht legt Mitarbeiter, Abwesenheiten, Schulungen, Dokumente usw. unter eigener Kennung an – der Chef sieht sie nicht, neue Mitarbeiter hängen am falschen Betrieb. Gleiches bei Tickets, Reports, Kalkulator-Normen.","Datenbank-Regeln mit Personal-Recht (wie Paket 181), dann Speichern für den Betrieb; Tabelle „mitarbeiter“ getrennt wegen Aussperr-Risiko.","G","2","live"),
("196","Elektro-Feinschliff","Prüfprotokolle haben keine Zahlenfelder für Messwerte, es fehlt die Erstprüfung nach VDE 0100-600; kein Elektro-Startkatalog, nur ein Kalkulator-Beispiel, keine Rechte-Vorlage „Monteur“.","Messwert-Felder mit Grenzwerten, Vorlage VDE 0100-600, Elektro-Startkatalog und Kalkulator-Beispiele (Zählerschrank, Wallbox, Unterverteilung), Rechte-Vorlage Monteur.","C","1","live"),
("197","Verschickte Rechnungen fest ablegen","Eine verschickte Rechnung wird nicht als PDF abgelegt; jedes Öffnen erzeugt sie neu aus den Daten. Jede spätere Änderung am Programm kann das Aussehen alter Rechnungen verändern.","Beim Versand wird das PDF unveränderbar abgelegt (mit Prüfsumme), Ansicht und Download zeigen danach immer genau dieses Dokument (GoBD).","G","1","live"),
("164·3","Zwei-Faktor auch in der Datenbank","Zwei-Faktor schützt nur die Seiten; mit gestohlenem Passwort sind Schnittstellen und Datenbank weiter voll nutzbar.","Datenbank-Regeln verlangen den bestätigten Code, danach Pflicht für alle einschalten. Hohes Aussperr-Risiko, mit Rückweg.","G","1","live"),
("198","Mahnungen und Zusagen fest ablegen","Mahnungen und Angebots-Zusagen werden bei jedem Öffnen neu erzeugt; verschickte Rechnungen bleiben bis „bezahlt“ änderbar; angenommene Angebote lassen sich nachträglich ändern.","Mahnungs-PDF und Zusage-Nachweis unveränderbar mit Prüfsumme ablegen, Rechnungen automatisch festschreiben (Zahlung, Mahnung, Zahlungsmeldung), angenommene Angebote gesperrt.","G","1","live"),
("199","Werbung: Bestätigung nachholen, Widerrufe, Bewertungen","Von Hand eingetragene Newsletter-Adressen bekommen nichts und lassen sich nicht bestätigen; die Seite kann „bestätigt“ selbst setzen. Nach der WhatsApp-Bestätigung kommt keine Antwort. Shop-Widerrufe sieht der Betrieb nur per Mail. Bewertungen zeigen den vollen Namen. „Unterlagen senden“ aus dem Kunden-Knopf ist ohne Werbe-Einwilligung blockiert.","Bestätigungs-Mail per Knopf nur mit Quelle + Datum der Einwilligung (höchstens 2, 7 Tage Abstand), Nachweis-Spalten nur noch vom Server, WhatsApp-„Danke, angemeldet“, Widerrufe auf der Retouren-Seite, Bewertungen als „Vorname + Initial“, Häkchen „Betriebspost“ am Kunden-Knopf.","C","1","live"),
("200","Rechte: Werkstatt-Bühne und „Angelegt von“","Die Werkstatt-Bühne verlangt das Recht „Buchungen“; wer einen Kontakt, ein Angebot, eine Rechnung oder einen Auftrag angelegt hat, sieht man nirgends.","Bühne auch mit Recht „Werkstatt“ buchbar, „Angelegt von“ in Kontakte, Angebote, Rechnungen, Aufträge.","C","1","live"),
("201","Mitglieder-Bankdaten schützen","Jeder Mitarbeiter kann über die Datenbank alle Mitglieder samt IBAN lesen (Regel mgd_select_ma).","Regel entfernen, Bankdaten in eigene Tabelle nur für Chef bzw. Mitglieder-Ändern-Recht. Getrennt geliefert (Aussperr-Hinweis).","G","1","live"),
("203","Zwei-Faktor-Ausnahmen je Mitarbeiter","Ohne Diensthandy muss der Chef die Zwei-Faktor-Pflicht für alle ausschalten.","Ausnahme-Liste je Mitarbeiter mit Grund und Nachweis. Getrennt geliefert (Aussperr-Hinweis).","G","1","live"),
("258","Speicher-Wächter nach AGB-Formel","Die Upload-Wege lasen die Tarif-Stufe aus einer Spalte, die fast nie passte: praktisch jeder Betrieb hatte 25 GB statt der AGB-Zusage 100 GB je Mitarbeiter.","Kontingent je Betrieb = Chef und Mitarbeiter × 100 GB, gepoolt, plus Zusatzblöcke, nie unter der alten Grenze; Mitarbeiter zählen zum Betrieb des Chefs; bei Störung 100 GB statt 25 GB. Getrennt geliefert.","C","1","live"),
("189","Voice Layer Stufe 2","Jede Wiedergabe erzeugt die Stimme neu und kostet jedes Mal.","Zwischenspeicher im privaten Speicher, gleiche Texte kosten nichts mehr.","C","1","wartet auf 188"),
("35–40","DSGVO-Werkzeuge (72er-Liste)","Verzeichnis und Auskunft haben 54 Lücken, es gibt keinen Löschweg für Leads, Webinar-Daten werden gelöscht statt gesperrt, keine Sperrung mit Fristen.","Vollständiges Verzeichnis mit Mustertexten, Löschweg, Sperren statt Löschen mit Fristen-Automatik – nach dem Anwalt.","C","2","wartet auf Anwalt"),
]))
S.append(("s3","Stufe 3 · Jetzt bauen","Neue Funktionen, ohne Pause bis kurz vor dem Anwalt – in dieser Reihenfolge",[
("B4","Shop aus Inventar","Die Übernahme ging nur über Filter; „Alle übernehmen“ stellte auch Artikel ohne Preis (0,00 €, so auch bestellbar) und ausgelistete Artikel in den Shop; jede Bestellung rechnete pauschal 19 % MwSt; Bilder nur per Adresse.","Übernahme per Häkchen-Auswahl oder Filter, nur aktive Artikel mit Preis (Rest mit Grund übersprungen), MwSt 19/7/0 % je Artikel, Foto-Upload, Filter „nur mit Bestand“; öffentlicher Shop zeigt und verkauft nur Verkaufsfähiges.","C","1","live"),
("S1","Kleines Sammelpaket aus dem Kontrollgang","Die Übungswelt nutzt echt existierende Beispiel-Domains; „Abmelden“ im Newsletter-Dashboard trägt nicht in die Sperrliste aller Kanäle ein.","Beispiel-Domains auf example.com, Abmelden wirkt in allen Kanälen.","C","1","live"),
("B5","Branchenverzeichnis-Eintrag","Einträge bei Google, Bing, Apple und den Verzeichnissen macht jeder Betrieb von Hand; Name, Adresse und Telefon stehen überall anders geschrieben.","Seite „Branchenverzeichnisse“: Eintrag aus den Firmendaten vorbereitet und überall gleich geschrieben (Telefon +49, Website https), jedes Feld per Klick kopieren, Beschreibung je Verzeichnis gekürzt, Lücken-Hinweis, abhaken mit Link und Datum.","C","1","live"),
("B3","Website-Texte aus Firmenwissen","„Komplett mit KI“ schrieb nur aus Name, Slogan, Über-uns und Story — Leistungskatalog und Firmen-Dokumente blieben ungenutzt; dazu erfand die KI immer Kundenstimmen („Beispiel-Bewertung“), die öffentlich erschienen.","KI nutzt Branche, Leistungskatalog (ohne Preise) und Firmen-Dokumente (vertraulich klingende nie), meldet die Quellen; statt erfundener Kundenstimmen der Baustein „Live-Bewertungen“ mit echten, freigegebenen Bewertungen; Schalter „Firmenwissen nutzen“.","C","1","live"),
("B1","Bausteine Presse, SEO-Texter, E-Book, Strategie, Social","Presse, SEO-Ratgeber, E-Book und Strategie gab es schon (Text-Werkstatt mit Prüf-Bestätigung). Bei Social fehlte sie: KI-Entwürfe aus dem Content-Fließband ließen sich ungeprüft posten oder einplanen; jeder Mitarbeiter konnte Beiträge anlegen und löschen.","KI-Entwürfe gekennzeichnet, Posten und Einplanen erst nach „Ich habe den Text geprüft“ (Textänderung hebt auf), auch im Zeitplan-Lauf; Beitrags-Schnittstelle mit Marketing-Recht. 1 statt 3 Pushes.","C","1","live"),
("B10","Fernhilfe: Bildschirm teilen","Braucht ein Mitarbeiter oder Kunde Hilfe, kann niemand sehen, was er gerade auf dem Bildschirm hat; es bleibt beim Beschreiben am Telefon.","Knopf „🆘 Hilfe“ oben im Dashboard: die Person wählt im Browser selbst Bildschirm, Fenster oder nur den ARGONAUT-Tab, schickt den Link an die Geschäftsleitung oder den ARGONAUT-Support, lässt den Helfer ausdrücklich zu; Bild direkt zwischen den Browsern, ohne Ton, ohne Aufzeichnung, rotes Band, jederzeit beenden, Passwort- und Bankfelder im ARGONAUT-Tab unscharf, Link 30 Min. gültig. 1 statt 2 Pushes.","C","1","live"),
("B7","Eigene Absender-Domain je Betrieb","Alle Kunden-Mails eines Betriebs (Rechnung, Termine, Newsletter, Abläufe …) gehen als „Firmenname <noreply@argonaut-os.com>“ – die Absender-Adresse gehört nicht dem Betrieb.","Betreiber legt die Domain im Command Center bei Resend an (Reiter „Absender-Domain“), der Chef sieht die DNS-Einträge in den Einstellungen; erst nach Bestätigung und Freischaltung gehen die Mails von z. B. rechnung@post.firma.de. Lehnt Resend die Domain später ab, geht die Mail automatisch über den Standard-Absender. Eine Domain nie bei zwei Betrieben. Scharf mit Env RESEND_EIGENE_DOMAINS=an (Pro 10 Domains, Scale 1.000).","G","1","live"),
("B9","Paket 2 Andocken","Die Menge im Kalkulator wird von Hand getippt, das Aufmaß mit Rechenweg kommt nie an. Die Projekt-Verknüpfung der Kalkulation gab es, gesetzt wurde sie nie – erfasste Stunden fließen nicht zurück, „Aus der Praxis lernen“ lernt nur aus den eigenen Schätzungen. Ob die geplante Marge gehalten hat, sieht niemand.","Kalkulator: „Menge aus Aufmaß übernehmen“ (Positionen ankreuzen, nur gleiche Einheit, Rechenweg bleibt), Projekt beim Speichern oder nachträglich verknüpfen; Liste zeigt Plan- gegen Ist-Stunden und die echte Marge (Ist-Lohn zum Kostensatz der Kalkulation, Projektkosten, gleicher Gemeinkosten-Zuschlag), Klartext-Hinweise; Zeit-Normwerte aus echten Projekt-Stunden als Vorschlag (Vorrang vor Schätzungen, nichts automatisch). 1 statt 2 Pushes.","G","1","live"),
("B6","Mitbewerber-Funktionen Top 15","Unklar, welche gängigen Funktionen führender Mitbewerber noch fehlen. Die Plantafel ging nur per Klick → Fenster → Datum und Monteur ändern → Speichern.","Abgleich mit 15 führenden Anbietern (intern, ohne Namen nach außen): 14 der 15 kaufentscheidenden Funktionen sind gebaut, Großhandels-Bestellung IDS/OCI hängt an Partner-Zugängen. Gebaut: Plantafel per Ziehen und Ablegen (Monteur, Tag, „Unzugeordnet“; Uhrzeit und Dauer bleiben; Rückfrage bei fehlender Befähigung oder Überschneidung; laufende und erledigte Einsätze bleiben fest). Weitere Lücken als B6b und B6c.","C","1","live"),
("B6b","Foto-Markierung im Bautagebuch","Fotos im Bautagebuch lassen sich nur hochladen und ansehen; ein Mangel ist auf dem Bild nicht eindeutig zu zeigen.","Knopf ✎ am Foto: Pfeil, Kreis, Rahmen, Freihand und Text mit Finger oder Maus, vier Farben, Rückgängig. Das Original bleibt unverändert (Beweisfoto), die markierte Fassung wird zusätzlich abgelegt (große Handyfotos auf 2.400 px verkleinert).","C","1","live"),
("B6c","Angebot aus Sprache oder Notiz","Im Mitbewerber-Abgleich als Lücke geführt — Prüfung am Code: gibt es schon seit Paket G01 (24.09.2026).","Im Angebotsformular „Angebot per Sprache/Foto“: diktieren, tippen oder Aufmaß-Zettel fotografieren, Positionsvorschlag mit Preisen nur aus Leistungskatalog oder belegter Preisliste. Kein neuer Push nötig.","C","0","live"),
("B11a","Dossier-Generator für alle 698 Branchen","Nur das Elektro-Dossier ist fertig; jede Branche braucht ein eigenes, korrektes Verkaufsdossier.","Generator nach dem Elektro-Richtwert: echte Module je Kategorie, Branchen-Beispiele, „in Vorbereitung“ mit Begründung, QR auf die Branchenseite – jetzt nur der Generator, noch keine Dossiers rausgeben.","C","1","live"),
("B11c","Fachdossier-Texte für alle freien Branchen","Der Generator lieferte für fast alle Branchen nur Entwürfe ohne geprüften Text; Sperren für heikle Bereiche (Gesundheit, Recht, Tiere, Kasse, Shop) und Start-Schalter fehlten; im Dossier stand „alles inklusive“ und der Agentur-Kostenvergleich.","Pakete 215–256: Kostenvergleich und „alles inklusive“ raus, Start-Schalter und Widerrufsbutton, Sperr-Gedächtnis mit Wächter-Test, dann Texte in Wellen je Bereich – nur gebaute Module, keine Rechts-, Norm- oder Zahlenversprechen, jede Welle mit eigenem Test und Gegenproben. Stand: 385 von 698 mit Text, 206 gesperrt bis zur Anwaltsprüfung, 107 bewusst zurückgestellt (Begründung je Test).","C","42","live"),
("B2","KI-Telefonassistent","Anrufe außerhalb der Zeiten gehen verloren; kein Telefon-Baustein.","Partner Retell oder Vapi, Termine und Anfragen landen im System, KI-Hinweis am Telefon.","G","2","wartet auf Partner"),
("B8","Echte Anmeldung Marketing-Plattformen","Zugänge zu Meta, Google, LinkedIn, TikTok werden von Hand eingetragen.","Anmeldung per Plattform-Login (OAuth), Zugänge verschlüsselt.","G","2","wartet auf App-Prüfung"),
("L1","Neues Logo: Segel-A","Überall stand noch das alte Dreizack-Zeichen aus der Anfangszeit (Emoji-Screenshot, nicht schützbar), dazu 🔱-Emojis auf Webseite, Kundenseiten, Dossiers und E-Books; Browser-Tab und App-Symbole waren Platzhalter.","Martins Segel-A (07.10.) vektorisiert: eine zentrale Form für Web, App und PDF-Zertifikat; Favicon, Apple- und App-Symbole, Linkvorschau, SVG in Gold/Schwarz/Weiß/Navy, Druck- und Social-Exporte. Alle 27 Emoji-Stellen ersetzt; Angebot und Kundenportal zeigen nur den Betriebsnamen. Offen: Markenrecherche DPMA/EUIPO (Anwalt).","C","2","live"),
("D1","Datensicherheit und Upgrade-Pfad","Hochgeladene Dateien liegen nur bei Supabase; die Wiederherstellung auf Zeitpunkt sichert nur die Datenbank, nicht die Dateien. Geht ein Kunden-Archiv verloren, haftet ARGONAUT. Kein festgelegter Plan, ab wann Rechenleistung, CDN-Stufe und Mail-Tarif hochgestuft werden.","Nach dem Bau, gemeinsam: zweite Kopie aller Dateien außerhalb Supabase (Auswahl Hetzner Object Storage Deutschland, Cloudflare R2, Backblaze B2 EU), versioniert und gegen Löschen gesperrt; Rücksicherung einmal echt üben. Alles streng je Betrieb getrennt: eigener Ordner, eigenes Kontingent, Export und Löschen je Betrieb. Upgrade-Stufen mit Auslösern festlegen (Supabase Large → XL → 2XL, Vercel CDN-Stufen, Resend Scale → Enterprise, Newsletter-Kontingent je Betrieb). Lieber ein paar Euro mehr für Sicherheit.","G","2","offen"),
]))
S.append(("kfz",'Stufe 3b · Kfz-Pilot','Nach den Fachdossiers · voller Umfang der führenden Kfz-Systeme plus eigene Extras, vom Gebrauchtwagenhändler bis zum Luxushaus · Branchen-Vorlage und Partner-Netzwerk als allgemeiner Kern, Kfz zuerst · 13 SQL-Blöcke · Abgleich mit Code 06.10. · 15 Rechtsfragen · Plan im Doc „ARGONAUT Bauplan Kfz-Handel“',[
('BV','Branchen-Vorlage (Kern)','Heute ist je Bereich festgelegt, welche Module ein Betrieb bekommt, und je Branche nur die Wortwahl. Spalten, Status, Ampeln, gespeicherte Suchen und Chef-Kacheln sind nicht je Branche vorbelegt.','Eigene Schicht Branchen-Vorlage: Vorbelegung je Bereich, Feinschliff je Branche, Kundenänderungen obendrauf (eigene Spalten, Felder, Status bleiben bei jedem Vorlagen-Update erhalten). Kfz ist die erste Vorlage, K1 nutzt sie von Anfang an.','C','1','live'),
('K1a','Fahrzeugbestand Teil 1','Es gibt Kundenfahrzeuge (Werkstatt, HU/AU, Reifenhotel), aber keinen Handelsbestand: keine Standtage, kein Status, keine Sparten, keine Vorführwagen- oder Kommissions-Kennzeichen.','Handelsbestand als Liste und Karten, Status Zulauf bis Archiv, Sparten PKW bis Wohnmobil, Standtage-Ampel, Massenbearbeitung, gespeicherte Suchen, Listendruck; Verknüpfung mit der Lebensakte per FIN.','C','1','live'),
('K1b','Fahrzeugbestand Teil 2','Bestandsliste nur am Bildschirm; die FIN ist gespeichert, aber noch nicht mit der Werkstatt-Lebensakte verknüpft; Eigene Felder fehlen im Bestand.','Bestandsliste als PDF mit den aktuellen Filtern, Hinweis „aus der Werkstatt bekannt“ über die FIN, Eigene Felder je Fahrzeug, Fotos-Platzhalter für K3.','C','1','live'),
('K2','Handelsakte','Die Fahrzeugakte kennt nur Werkstatt und Halter, nichts zum Verkauf; fehlende Fotos und CO₂-Angaben fallen nicht auf.','Reiter Überblick, Ausstattung, Bilder, Akte, Historie, Aktionen; Preisverlauf, Inserats-Ampel, Titel-Wächter, CO₂-Felder; Link zur bestehenden Lebensakte.','C','1','live'),
('K3','Fotos und Medien','Fahrzeugfotos nur einzeln, keine Reihenfolge, keine Aufnahme-Hilfe.','Handy-Upload mit Aufnahme-Schablone, Reihenfolge per Ziehen, Video; Schäden über die vorhandene Foto-Markierung.','C','1','live'),
('K4a','Ankauf und Bewertung Teil 1','Kein Ankaufsprotokoll, keine Bewertung von Ankaufsfahrzeugen.','Ankaufsakte mit Prüfprotokoll (24 Punkte), Schäden mit Foto und Markierung, Richtwerte je Schadensart, Höchstpreis nach § 25a oder Regelsteuer, Angebots-Ampel, Übernahme in den Bestand mit einem Klick.','G','1','live'),
('K4b','Ankauf und Bewertung Teil 2','Kein Ankaufschein, keine Online-Anfrage für Verkäufer.','Ankaufschein als PDF zum Unterschreiben (Schäden ohne Beträge, Unternehmen mit USt), Online-Ankaufformular mit eigenem Link für Webseite und Inserate, Ein-/Ausschalter, Mail an Betrieb und Eingangsbestätigung. Inzahlungnahme am Verkauf wandert zu K6.','G','1','live'),
('K5','Kalkulation und Provision','Provisionen nur aus Deals; Ertrag je Fahrzeug unbekannt.','Plan- und Nachkalkulation je Fahrzeug mit Standkosten und Gemeinkosten, Provision Verkäufer und Hereinnehmer, Kommission.','C','1','live'),
('K6','Verkaufsunterlagen','Kein Kaufvertrag, keine Reservierung, keine Zulassungsvollmacht.','Verkaufsvorgang je Fahrzeug (Doppelverkauf sperrt die Datenbank): Angebot, Reservierung, Quittung Anzahlung, Kaufvertrag (Verbraucher/Unternehmer, Verkürzung auf ein Jahr nur gesondert mit eigener Unterschrift), Zulassungsvollmacht, Empfangsbestätigung als PDF; Inzahlungnahme aus dem Ankauf verrechnet; Unterschrift über ARGONAUT-Sign; ab 10.000 € bar kein Vertrag ohne GwG-Haken; Bestand-Status und Erlös in der Kalkulation ziehen mit; Übersicht „Verkäufe“.','G','1','live'),
('267','Stornorechnung als eigener Beleg','„Stornieren“ setzte nur den Status. Eine verschickte Rechnung brauchte für die Aufhebung einen eigenen Beleg mit Nummer und Verweis – den gab es nur als freies Dokument ohne Nummernkreis und Ablage.','Stornorechnung mit eigener Nummer aus dem Rechnungs-Nummernkreis, alle Positionen mit umgekehrtem Vorzeichen, Verweis auf das Original, sofort festgeschrieben, erstes PDF automatisch abgelegt, kein Zahlbetrag und kein GiroCode, Erstattungshinweis bei bezahlten Rechnungen; in einem Schritt in der Datenbank, nur Geschäftsleitung, kein Reaktivieren danach. Nie verschickte Rechnungen weiter per Status. Getrennt geliefert (Kern-Geld).','G','1','live'),
('K7','Rechnung Fahrzeugverkauf','§ 25a steht nirgends im Code; Gebrauchtwagen würden mit Umsatzsteuer ausgewiesen. Freitext-Empfänger standen ohne Anschrift auf dem PDF.','Rechnung aus dem Verkauf per Knopf: § 25a ohne Steuerausweis mit Pflichthinweis „Gebrauchtgegenstände/Sonderregelung“, Zulassung und Überführung mit 19 %; Regelsteuer centgenau auf den Vertragspreis (nie mehr); EU-Unternehmer und Ausfuhr steuerfrei mit Pflichthinweis und Nachweis-Hinweisen; Inzahlungnahme und Anzahlung mindern nur den Zahlbetrag; Differenzsteuer intern gespeichert; E-Rechnung mit E/K/G-Kategorie; Empfänger-Anschrift und USt-IdNr. auf jedem Rechnungs-PDF; Doppelschutz. Getrennt geliefert (Kern-Geld).','G','1','live'),
('269','Umsatzsteuer-Voranmeldung: § 25a, EU, Ausfuhr','Die Voranmeldung rechnet nur mit Netto und Steuer je Rechnung: eine § 25a-Rechnung erscheint als steuerfreier Umsatz, die Differenzsteuer fehlt; EU-Lieferungen und Ausfuhren landen ohne Kennziffer im Topf „steuerfrei“.','Marge netto der § 25a-Rechnung in Kz 81, Differenzsteuer in der Zahllast, der Verkaufspreis selbst wird nicht gemeldet; EU-Lieferung in Kz 41 (Hinweis Zusammenfassende Meldung), Ausfuhr in Kz 43; fehlt die Differenz, sagt die Seite laut „zu wenig gemeldet“. Rechnungen ohne Sonderfall unverändert. Getrennt geliefert (Kern-Geld).','G','1','live'),
('K9','Probefahrt und Vorführwagen','Fuhrpark und Verleih kennen keine Probefahrt und keine roten Kennzeichen.','Reiter „Probefahrt“ in der Handelsakte für Probefahrt, Vorführwagen, Ersatzwagen und Überführung: Führerschein nur als Prüfvermerk mit Klasse und Gültigkeit (keine Nummer), eigenes, rotes oder Kurzzeitkennzeichen (nie doppelt belegt), Übergabe und Rückgabe mit km, Tank und Schäden, Vereinbarung und Rückgabeprotokoll als PDF und zur Unterschrift; Kilometerstand der Akte zieht nach; Nachfass zwei Tage nach Rückgabe als Erinnerung; Übersicht „Probefahrten“ mit Überfällig, Nachfass und Fahrtenliste je rotem Kennzeichen.','C','1','live'),
('K10','Leads und Suchaufträge','Anfragen hängen nicht am Fahrzeug; Kundenwünsche gehen verloren.','Seite „Anfragen und Suchaufträge“: Anfrage mit oder ohne Fahrzeug, Quelle, Verantwortlicher per Klick, nächster Kontakt mit Ampel (überfällig/heute), Stand bis Gewonnen/Verloren mit Grund, Auswertung der Verlustgründe und Quellen, Abschlussquote; Suchaufträge mit 90 Tagen Laufzeit und Treffern aus dem Bestand („neu seit letztem Blick“); Hinweis in der Fahrzeugakte. Eigene Tabellen statt „leads“ — keine Werbe-Serie startet.','C','1','live'),
('K11a','Eigene Fahrzeugbörse','Keine eigene Fahrzeugbörse; Interessenten sehen den Bestand nirgends, Anfragen kommen nur per Telefon oder Mail.','Öffentliche Börse je Betrieb (Link zum Teilen, vom Chef ein- und ausschaltbar): nur inserierte Fahrzeuge in Bestand, Aufbereitung oder Zulauf, Filter und Sortierung, Detailseite mit Fotos, Preis als Endpreis (bei § 25a ohne Steuerausweis), Fahrzeugdaten, Energie und CO₂, Ausstattung, Unfall-Angabe ehrlich; Anfrage-Formular landet als Anfrage am Fahrzeug (Quelle Webseite, heute fällig) mit Mail an den Betrieb; bei Google auffindbar mit Fahrzeug-Strukturdaten (abschaltbar); EK, Kalkulation, FIN, Kennzeichen, Notizen nie öffentlich (Positivliste, Wächter-Tests); Impressum und Datenschutz-Hinweis des Betriebs; Hinweisleiste, wo Preis, Energie oder Firmendaten fehlen.','C','1','live'),
('273','Börse auf der Domain des Händlers','Die Börse lief nur unter argonaut-os.com; auf der Domain des Händlers zeigte /fahrzeuge die Startseite, Google hätte die Fahrzeuge unter unserer Domain geführt.','autohaus-domain/fahrzeuge zeigt die Börse (Betrieb nur über die Domain aus dem Website-Bauer, auch Subdomain), Google-Adresse immer auf der Händler-Domain, Menüpunkt „Fahrzeuge“ auf der Kunden-Webseite, Domain nur für die Börse leitet auf /fahrzeuge; offen „Präsentiert mit ARGONAUT OS“ im Fuß jeder Börse und Kunden-Webseite (nur Marke). Keine versteckte Weiterleitung über argonaut-os.com.','C','1','live'),
('274','Partner-Andockstelle und Fahrzeughistorie','Partner wie carVertical ließen sich nirgends anbinden; ein Historienbericht hing nicht am Fahrzeug, Käufer sahen in der Börse keinen Nachweis.','Muster für alle Partner: in der Schnittstellen-Zentrale je Partner zwei Wege, eigenes Konto verbinden (Schlüssel verschlüsselt) oder „Noch kein Konto? Hier abschließen“ direkt beim Partner (ARGONAUT vermittelt nur, verkauft nichts weiter). Erster Partner carVertical: Bericht-Link mit Datum in der Akte, „Fahrzeughistorie geprüft“ in der Börse nur mit Freigabe je Fahrzeug. Abruf per Knopf folgt mit K19.','C','1','live'),
('275','K12a Preise und Standzeit','Preise wurden nach Gefühl gesenkt: keine Untergrenze je Fahrzeug, kein Überblick über Standzeiten, keine Zahl, wie oft ein Fahrzeug in der eigenen Börse angesehen wurde.','Preis-Cockpit über den ganzen Bestand nur aus eigenen Daten: Untergrenze (Einkauf + Kosten + Standkosten + Mindest-Rohertrag), Standzeit-Verteilung mit gebundenem Einkauf, Aufrufe der Börse ohne Cookies, Anfragen, Inserats-Ampel, Einschätzung in Klartext; Vorschlag nur nach der eigenen Preis-Treppe (keine KI), Übernahme per Knopf mit Preisverlauf.','C','1','live'),
('276','K12b Marktvergleich','Ob ein Preis zum Markt passt, sah der Händler nur durch Suchen auf den Börsen; nichts davon landete am Fahrzeug.','Vergleichsangebote je Fahrzeug selbst erfassen (Preis, km, Erstzulassung, Quelle, Link, keine Namen); Marktmitte, Spanne als Balken, Rang und Abweichung, km-Hinweis; zählt nur Einträge der letzten 30 Tage, die nach km und Erstzulassung passen, ab 3 eine Aussage. Auch im Preis-Cockpit. Keine fremden Marktdaten, keine KI; lizenzierter Partner kann später andocken.','C','1','live'),
('277','K13 Brief-Tresor und Aufbereitung','Unklar, wo Fahrzeugbriefe und Schlüssel liegen, wer sie gerade hat und welches Fahrzeug in der Aufbereitung steht; der Brief konnte vor der Zahlung herausgegeben werden.','Tresor je Fahrzeug (Brief, Schein, Schlüssel, CoC, Serviceheft) mit Ort, Ausgabe an wen und bis wann, Verlauf nur durch die Datenbank; Brief an den Käufer gesperrt, solange Geld offen ist. Zulassungsauftrag (Zulassung, Ummeldung, Abmeldung, Ausfuhr, Kurzzeit) mit Unterlagen-Haken und eVB. Aufbereitung als interner Auftrag im Werkstatt-Board ohne Kundenrechnung, Kosten per Knopf in die Kalkulation. Übersicht mit überfälligen Ausgaben und Briefen nicht im Haus.','C','1','live'),
('278','K18a Partner-Netzwerk: Verbindung, Auftrag, Einträge','Jeder Betrieb ist streng getrennt; ein Händler kann seinem Aufbereiter, Lackierer oder Gutachter keinen Auftrag am Fahrzeug geben, der dort in die Akte schreibt. Passt für 390 von 698 Branchen (300 ohne Anwalt).','Verbinden per Einladungs-Code (nur Geschäftsleitung, 14 Tage, einmalig, jederzeit trennbar), Auftrag am Fahrzeug an den Partner mit Freigaben (km, FIN, Fotos), Partner sieht nur dieses Fahrzeug ohne Preise, Kunde, Kennzeichen und Notizen und nur, solange der Auftrag läuft; Annehmen/Ablehnen/Fertig/Abnehmen/Nachbesserung, Einträge und Fotos beider Seiten nicht änderbar (privater Ordner ohne Regeln, nur der Server), Glocke. Zugriff ausschließlich über geprüfte Datenbank-Funktionen.','G','1','live'),
('279','K18b Partner-Netzwerk: Gast-Link und Partner-Rechnung','Partner ohne ARGONAUT können nicht mitarbeiten; die Rechnung des Partners kommt per Mail und muss von Hand in Belegeingang und Kalkulation.','Gast-Link je Auftrag (nur Prüfwert gespeichert, 7–60 Tage, sperrbar, Mengen-Deckel, nie bei Google): Gast sieht nur diesen Auftrag, nimmt an, schreibt Einträge mit Fotos, meldet fertig. Partner (Betrieb oder Gast) reicht Rechnung ein (PDF/Foto, Netto, USt 19/7/0 %); Auftraggeber übernimmt sie per Knopf in Belegeingang (Fremdleistung, mit Datei) und Fahrzeugkosten — in einem Schritt, nie doppelt — oder weist sie mit Grund zurück. Rechtsfrage AV-Vertrag zwischen Betrieben (R47).','G','1','live'),
('280','K14 Chef-Blick Fahrzeughandel','Keine Auswertung, womit der Fahrzeughandel Geld verdient.','Nur Chef: Kacheln Monat/Quartal/Jahr gegen Vorjahr (Verkäufe, Erlös, Rohertrag, Deckungsbeitrag, Standtage), Rohertrag je Monat als Balken, Ertrag je Marke und Preisklasse, Zulauf und gebundener Einkauf, Verkäufer-Rangliste (Standard aus, § 87 BetrVG), Summen-Wächter in ganzen Cent. Karte im Chef-Blick, Quelle „Fahrzeughandel“ im Report-Baukasten. Kein SQL, keine KI.','C','1','live'),
('281','K15a Kaufstatus im Kundenportal','Käufer sehen den Stand ihres Kaufs nicht. Ein Verkaufsvorgang war nie mit einem Kontakt verknüpft — Rechnung und Portal kannten den Käufer nicht.','Karte im Reiter „Verkauf“: Käufer mit Kontakt verknüpfen (Vorschlag nur bei eindeutig gleicher E-Mail, sonst neu anlegen oder suchen), Kaufstatus-Link erstellen. Im Portal ab „reserviert“: Schritte bis zur Übergabe, Zulassung, Kaufpreis mit Anzahlung, Inzahlungnahme und Restbetrag, Stand des Fahrzeugbriefs — nie Einkauf, FIN oder Notizen. Kein SQL.','G','1','live'),
('282','K15b Finanzierungs-Beispiel und Konfigurator','Kein Finanzierungs-Beispiel; Zusatzleistungen (Winterräder, Garantie, Zulassung) kann der Interessent nicht selbst zusammenstellen.','Börse → Einstellungen: bis 12 Zusatzleistungen zum Ankreuzen (Preise rechnet der Server aus der Liste, Auswahl steht in der Anfrage). Finanzierungsbeispiel mit allen Pflichtangaben (§ 17 PAngV), effektiver Jahreszins aus den Raten, Rate auf den Cent aufgerundet; im Inserat nur mit Darlehensgeber, Anschrift, Sollzins und Bestätigung „Konditionen von der Bank“. Rechner fürs Verkaufsgespräch. ARGONAUT vermittelt keine Kredite. Kein SQL.','G','1','live'),
('283','K16a Fahrzeugbestand-Import und Bewertung DAT/Schwacke','Der Import kennt 81 Alt-Programme, aber kein Kfz-System; Händler tippen ihren Bestand ab. DAT- und Schwacke-Werte stehen nirgends am Fahrzeug.','Ziel „Fahrzeugbestand“ im Import-Center: eigene Listen und die mobile.de-Upload-Datei (feste Felder nach Handbuch), Monat/Jahr, PS → kW, ungültige FIN in die Notiz statt Zeile weg. Gruppe „Autohaus & Kfz-Handel“ (mobile.de belegt; Loco-Soft, WERBAS, Keyloop, incadea, AutoScout24 ehrlich „beim Hersteller erfragen“). Karte „Bewertung“ in der Akte: FIN kopieren, im eigenen DAT-/Schwacke-Konto abfragen, Händlerwerte eintragen, Vergleich mit dem eigenen Preis; Schnittstellen-Zentrale „Fahrzeugbewertung“ mit beiden Wegen. SQL getrennt.','C','1','live'),
('284','K16b DATEV: § 25a, EU und Ausfuhr richtig buchen','Der DATEV-Export kannte keine Kfz-Sonderfälle: ein Verkauf nach § 25a mit Zulassung landete als 7-%-Umsatz auf 8300 (DATEV hätte rund 1.347 € Steuer erfunden), ohne Zusatz steuerfrei auf 8200 — die Differenzsteuer fehlte. EU-Lieferung und Ausfuhr ohne eigenes Konto.','Kfz-Rechnungen werden aufgeteilt: § 25a Marge auf 8191/4136 (19 %), Rest ohne USt auf 8193/4138, EU 8125/4125, Ausfuhr 8120/4120, Zusatzleistungen wie üblich; Summe centgenau. Konten unter Schnittstellen → DATEV einstellbar, Fahrzeugnummer im Buchungstext, Hinweise vor dem Export; fehlen Positionen, wird nicht geraten. Kein SQL.','G','1','live'),
('285','K17a Musterbetrieb mit Handelsbestand','Der Musterbetrieb XXL hatte Werkstatt und Kundenfahrzeuge, aber keinen Handelsbestand — die Kfz-Seiten waren am Testtag leer.','8 Handelsfahrzeuge in jedem Status (Zulauf bis verkauft, auch Vorjahr für den Chef-Blick, ein Langsteher, ein Motorrad), Kosten, 4 Marktvergleiche, Anfragen, Suchauftrag, Probefahrt, Brief-Tresor, DAT-Bewertung. Kein Kaufvertrag, keine Rechnung, Börse bleibt aus. Kein SQL.','C','1','live'),
('286','K17b Kfz-Fachdossier','Das Fachdossier für den Kfz-Handel beschrieb noch Pipeline und Termine — nichts vom Kfz-Pilot (Ankauf, Börse, Probefahrt, Verkauf, Tresor, Kalkulation).','Kfz-Handel-Dossier neu nach dem Elektro-Richtwert: Alltag, Ablauf (Börse → Probefahrt → Kaufvertrag → Rechnung/Brief → Übergabe), Schwerpunkt Kalkulation je Fahrzeug und eine neue Seite „Ihr Fahrzeughandel im Detail“ (16 gebaute Funktionen, Partner carVertical, DAT, Schwacke über das eigene Konto). Nur Gebautes (Regel aus Paket 217) — Wartendes steht bewusst nicht drin. Neues PDF wird beim nächsten Abruf erzeugt. Kein SQL.','C','1','live'),
('C1','Einwilligungs-Fenster und Besucher-Tracking mit Cookies','Kunden-Webseiten und Börse zählen nur ohne Cookies (Tageskennung); wiederkehrende Besucher und Kampagnen-Wege über mehrere Tage sind nicht messbar.','Eigenes Einwilligungs-Fenster (Annehmen und Ablehnen gleichwertig, Nachweis, jederzeit widerrufbar), erst danach eigenes Tracking-Cookie, Daten bleiben bei ARGONAUT (kein Google Analytics); wer ablehnt, wird weiter ohne Cookies gezählt; Datenschutz-Text des Betriebs ergänzt. Nach dem Kfz-Pilot, mit Anwalt-Punkt (§ 25 TDDDG).','G','2','offen'),
('BV2','Branchen-Vorlagen für alle Bereiche','Nach Kfz haben die übrigen 18 Bereiche noch keine vorbelegten Spalten, Status, Ampeln und Kacheln.','Vorlagen Bereich für Bereich nach dem Kfz-Muster, je Branche Feinschliff; Reihenfolge nach Betriebszahl, Handwerk und Bau zuerst.','C','4','offen'),
('BV2b','Handel mit Einzelstücken','Das Kfz-Gerüst (Bestand, Akte, Ankauf, Kalkulation, § 25a, Börse, Anfragen, Preis-Cockpit, Marktvergleich) gibt es nur für Fahrzeuge.','Vorlagen-Technik verallgemeinern (Merkmal-Sätze und Begriffe je Branche), dann Boote/Wohnmobil/Motorrad, Land- und Baumaschinen/Stapler (Betriebsstunden), Uhren/Schmuck/Kunst/Antiquitäten (§ 25a, GwG), Fahrrad/Second Hand. Immobilien-Objektbörse erst nach dem Anwalt (+2).','C','7','offen'),
('PS-1','Preis-Spiegel für Dienstleister','Friseur, Gastronomie oder Handwerk wissen nicht, wo ihre Preise im Umfeld liegen.','Preise von Mitbewerbern von Hand erfassen (keine Namen von Personen, kein Auslesen), Marktmitte und Position wie im Kfz-Marktvergleich.','C','1','offen'),
('BV3','Manufaktur und Feinkost','Premium-Lebensmittel (Dry-Aged, Käse, Wein, Confiserie) haben Chargen, Reifezeit und knappe Mengen — dafür gibt es kein Gerüst.','Chargenakte mit Reife-Uhr, Kalkulation mit Reifeverlust, Preis-Treppe nach Reife/MHD, Schaufenster mit Vorbestellung, Vormerkliste und LMIV-Wächter, Box-Konfigurator mit Saison-Kapazität; Pilot Fleischveredler, dann Wein, Confiserie. Freischalten erst nach dem Anwalt (Lebensmittel).','C','6','offen'),
]))
S.append(("alle","Stufe 3c · Für alle Branchen","Was jeder Betrieb braucht – aus dem Kfz-Pilot heraus für alle 698 Branchen",[
("RF1","Rechts-Freigaben-Zentrale","Heikle Funktionen (Ortung, Führerschein-Prüfung, Bonitätsprüfung, Kameras, Aufzeichnung) wären entweder für alle an oder gar nicht da; ob der Betrieb Mitarbeiter und Kunden informiert, einen Betriebsrat beteiligt oder einen Vertrag mit dem Dienstleister hat, weiß ARGONAUT nicht.","Eine Seite „Rechtliche Freigaben“: je heikler Funktion die Voraussetzungen als Häkchen mit Vorlage (Hinweistext, Einwilligung, Betriebsvereinbarung, Vertrag), Nachweis wer/wann/welche Fassung, jährliche Erneuerung. Erst dann schaltet die Funktion frei; ohne Freigabe bleibt sie gesperrt mit Erklärung. Vorlagen nach dem Anwalt.","G","2","nächster"),
("F1","Fuhrpark-Pflichten für alle Betriebe","Jeder Betrieb mit Firmenwagen muss die Führerscheine seiner Fahrer regelmäßig prüfen (sonst Halterhaftung) und braucht für die Steuer ein unveränderbares Fahrtenbuch — beides fehlt.","Führerschein-Kontrolle mit Prüfvermerk (ohne Kopie), Intervall und Erinnerung; elektronisches Fahrtenbuch (zeitnah, nachträglich nur mit Änderungsprotokoll, GoBD-Sperre); UVV-Prüfung, Ladekosten zu Hause erstatten. Hängt am vorhandenen Fuhrpark.","C","2","offen"),
("J1","Jobticket, Dienstrad und Mobilitätszuschuss","Betriebe zahlen Zuschüsse zum Deutschlandticket oder ein Dienstrad, führen Nachweise aber in Excel; was steuerfrei ist und was in die Lohnabrechnung gehört, sieht niemand.","Je Mitarbeiter: Jobticket-Zuschuss, Dienstrad, Ladestrom, Fahrtkosten mit Nachweis, Laufzeit und Hinweis für die Lohnabrechnung (steuerfrei oder pauschal — Steuerberater bestätigt), Erinnerung bei Ablauf; Übersicht Kosten je Monat.","C","1","offen"),
("N1","Betriebs-Netzwerk für alle Branchen","Das Partner-Netzwerk (K18) gibt es nur im Kfz-Handel; Gewerke am Bau, Subunternehmer, Freelancer und Zulieferer arbeiten weiter per Mail und Telefon.","Partner-Aufträge, Einträge mit Fotos, Gast-Link und Partner-Rechnung in den Belegeingang auch für Projekte, Aufträge und Objekte — jeder sieht nur seinen Teil.","C","2","offen"),
("SP1","„Was ARGONAUT Ihnen gespart hat“","Der Nutzen von ARGONAUT ist für den Chef nicht in Euro sichtbar — und für Social Media gibt es keine belegten Zahlen.","Karte im Chef-Blick nur mit messbaren Werten (genutztes Skonto, Verzugszinsen, ersetzte Programme laut Umzug, THG-Prämie, Importe statt Abtippen); Freigabe zum Teilen nur mit Einwilligung des Betriebs.","C","1","offen"),
]))
S.append(("mob","Stufe 3d · Mobilität","Nach dem Kfz-Pilot · Kfz-Gerüst für Vermietung, Zweirad, Flotte und Motorsport wiederverwenden · heikle Funktionen nur mit Rechts-Freigabe",[
("V1","Fahrzeugvermietung Kern","Autovermietung, Luxusverleih, Wohnmobil-, Transporter-, Motorrad- und E-Bike-Verleih haben eine Branchenseite, aber kein Fachmodul.","Ein gemeinsames Modul aus dem Kfz-Gerüst: Mietflotte, Buchung mit Kalender ohne Doppelbuchung, Mietvertrag, Mindestalter und Führerschein-Dauer, Kaution über den Zahlungsanbieter des Betriebs (nie Kartendaten bei ARGONAUT), Übergabe/Rückgabe mit Fotos, km, Tank, Schäden, Zusatzfahrer, Rechnung.","C","2","offen"),
("V2","Vermietung: Online-Buchung, Bußgelder, Auslastung","Mieter buchen per Telefon; Halteranfragen und Bußgelder werden von Hand zugeordnet; niemand sieht, welches Fahrzeug sich lohnt.","Online-Buchung in Börse und Webseite, Halteranfrage → Mieter zum Zeitpunkt finden, Fahrer benennen, Bearbeitungsgebühr; Auslastung und Ertrag je Fahrzeug, Wartungs- und HU-Fristen.","C","1","offen"),
("V3","Ortung und Telematik über Partner","Ortung von Miet- und Firmenfahrzeugen gibt es nicht.","Anbindung eines Telematik-Partners (Konto des Betriebs, ARGONAUT vermittelt nur); freigeschaltet erst über die Rechts-Freigaben-Zentrale (Zweck, Information, Betriebsrat, Vertrag), Standort nur bei Diebstahl/Rückgabe statt Dauerbeobachtung.","G","1","wartet auf RF1"),
("Z1","Zweirad, E-Bike und Dienstrad-Leasing","Motorrad läuft über den Kfz-Feinschliff; E-Bike-Händler haben keine Rahmen-/Akkunummern, keine Dienstrad-Abwicklung mit Leasing-Portalen.","Rahmen- und Akkunummer, Inspektionen, Garantie, Dienstrad-Vorgang (Angebot, Leasing-Portal, Übergabe, Rechnung an den Leasinggeber), Reparatur-Annahme.","C","1","offen"),
("T1","Trackday, Rennschule, Kartbahn","Motorsport-Veranstalter buchen per Mail und Excel, Haftungsverzichte liegen auf Papier.","Event-Buchung mit Startplätzen, Haftungsverzicht digital unterschrieben, Leihfahrzeuge aus V1, Teile mit Laufzeit je Teil, Sponsoren und Gäste.","C","1","offen"),
("P1","Personenbeförderung: Taxi, Mietwagen mit Fahrer, Bus","Taxi-, Mietwagen- und Busunternehmen haben nur die Branchenseite; Konzessionen, Fahrer-Nachweise und Lenkzeiten fehlen.","Konzessionen und Fristen, Fahrer mit Personenbeförderungsschein, Fahrten und Abrechnung, Lenk- und Ruhezeiten aus Fahrtenschreiber-Dateien — nach dem Anwalt.","G","2","wartet auf Anwalt"),
]))
S.append(("s4","Externe Partner · kurz vor dem Anwalt vorbereiten","Code so weit wie möglich (Sandbox), dazu Schritt-für-Schritt-Anleitung, was Martin beantragt",[
("E1","BANKSapi – Bankumsätze automatisch","Bankumsätze nur per Datei-Import (CSV, CAMT, MT940).","Automatischer Abruf über BANKSapi BANKS/Connect (BaFin-Lizenz liegt bei BANKSapi, Abrechnung je Nutzer), Abgleich mit offenen Rechnungen. 32 Testtage komplett nutzen (Sandbox und echte Banken), danach Starter mit 36 Monaten Laufzeit (rund 33 % Rabatt).","G","2","wartet auf Testzugang"),
("E2","Echte Kassen-TSE","Die Kasse läuft nur im Demo-Modus ohne echte TSE.","Anbindung fiskaly oder Deutsche Fiskal, Kassen-Meldung.","G","1","wartet auf Konto"),
("E3","DATEVconnect","DATEV nur als Datei-Export.","Direkte Übergabe an den Steuerberater über DATEVconnect.","C","1","wartet auf Zugang"),
("E4","Shop- und Versand-Schnittstellen","Shopware, Shopify, WooCommerce und DHL sind gebaut, aber nie mit echtem Konto getestet.","Test mit echten Konten, Fehler beheben.","C","1","wartet auf Testkonten"),
("K11b","Fahrzeugbörsen mobile.de und AutoScout24","Fahrzeuge müssen in mobile.de und AutoScout24 von Hand eingestellt werden; die eigene Börse (K11a) läuft, die großen Börsen nicht.","Hochladen und Abgleich über das Konto des Händlers (mobile.de Seller-API, AutoScout24/TruckScout24 Listing-API): Fahrzeuge, Fotos, Preisänderungen, Verkauft-Meldung; Anfragen der Börsen in „Anfragen und Suchaufträge“. Braucht Händler-Vertrag und API-Zugang.","G","1","wartet auf Händler-Zugang"),
("E5","THG-Quote für E-Fahrzeuge (Partner)","Betriebe mit E-Autos verschenken jedes Jahr die THG-Prämie, weil niemand daran denkt.","Partner-Andockstelle wie carVertical: Fahrzeugschein im eigenen Konto beim Partner einreichen, Erinnerung jedes Jahr; ARGONAUT vermittelt nur.","C","1","wartet auf Partner"),
("K19","carVertical: Bericht per Knopf (API)","Händler kaufen Historienberichte getrennt; Käufer sehen in der Börse keinen unabhängigen Nachweis zu Unfällen, Kilometerstand und Diebstahl.","Bericht-Link und Siegel sind mit Paket 274 live; jetzt über die B2B-API Bericht per FIN direkt aus der Handelsakte bzw. beim Ankauf, Abrechnung über das Konto des Händlers. Braucht Partner-Vertrag und API-Zugang; Anwalt: Weitergabe der FIN, Werbung mit Siegel.","G","1","wartet auf Partner-Vertrag"),
]))
S.append(("s5","Nach der Abnahme durch den Anwalt","Erst wenn alles rechtlich freigegeben ist",[
("B11b","Branchen-Dossiers freigeben und rausgeben","385 Dossiers haben geprüften Text, rausgegeben wird aber noch keins; 206 Branchen sind bis zur Anwaltsprüfung gesperrt, 107 bewusst zurückgestellt (Liste für den Anwalt).","Nach der Freigabe: gesperrte Bereiche öffnen und Texte schreiben, zurückgestellte Branchen einzeln nachziehen, dann Dossiers ausgeben – nur Gebautes, „in Vorbereitung“ mit Begründung.","C","1","wartet auf Anwalt"),
]))
